using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Testing;

namespace Receipts.GeneratedTests;

public class CharacterizeEnumTemplateTests
{
    [Fact]
    public async Task EnumFormatterSerializesUsingItsUnderlyingType()
    {
        const string Source = """
            using MessagePack;

            [MessagePackObject]
            public class EnumHolder
            {
                [Key(0)]
                public SampleEnum Value { get; set; }
            }

            public enum SampleEnum : short
            {
                None = 0,
                One = 1,
            }
            """;

        string generated = await RunGeneratorAsync(Source);

        Assert.Contains("SampleEnumFormatter", generated);
        Assert.Contains("IMessagePackFormatter<global::SampleEnum>", generated);
        Assert.Contains("writer.Write((short)value)", generated);
        Assert.Contains("(global::SampleEnum)reader.ReadInt16()", generated);
    }

