using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Testing;

namespace Receipts.GeneratedTests;

public class CharacterizeUnionTemplateTests
{
    [Fact]
    public async Task UnionFormatterContainsSubtypeDispatchAndNilHandling()
    {
        const string Source = """
            using MessagePack;

            [Union(0, typeof(TextMessage))]
            [Union(1, typeof(ImageMessage))]
            public interface IMessage
            {
            }

            [MessagePackObject]
            public class TextMessage : IMessage
            {
                [Key(0)]
                public string Text { get; set; }
            }

            [MessagePackObject]
            public class ImageMessage : IMessage
            {
                [Key(0)]
                public int Size { get; set; }
            }
            """;

        string generated = await RunGeneratorAsync(Source);

        Assert.Contains("IMessagePackFormatter<global::IMessage>", generated);
        Assert.Contains("typeToKeyAndJumpMap", generated);
        Assert.Contains("typeof(global::TextMessage).TypeHandle", generated);
        Assert.Contains("typeof(global::ImageMessage).TypeHandle", generated);
        Assert.Contains("writer.WriteArrayHeader(2)", generated);
        Assert.Contains("writer.WriteInt32(keyValuePair.Key)", generated);
        Assert.Contains("writer.WriteNil()", generated);
        Assert.Contains("reader.ReadArrayHeader() != 2", generated);
        Assert.Contains("reader.Skip()", generated);
    }

    private static async Task<string> RunGeneratorAsync(string source)
    {
        var references = (await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None))
            .AddRange(ReferencesHelper.GetReferences(ReferencesSet.MessagePack));
        CSharpCompilation compilation = CSharpCompilation.Create(
            "Receipts_" + Guid.NewGuid().ToString("N"),
            new[] { CSharpSyntaxTree.ParseText(source, new CSharpParseOptions(LanguageVersion.CSharp7_3)) },
            references,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        GeneratorDriver driver = CSharpGeneratorDriver.Create(new MessagePack.SourceGenerator.MessagePackGenerator().AsSourceGenerator());
        driver = driver.RunGeneratorsAndUpdateCompilation(compilation, out Compilation outputCompilation, out ImmutableArray<Diagnostic> diagnostics);

        Assert.Empty(diagnostics.Where(d => d.Severity == DiagnosticSeverity.Error));
        Assert.Empty(outputCompilation.GetDiagnostics().Where(d => d.Severity == DiagnosticSeverity.Error));
        return string.Join("\n", driver.GetRunResult().GeneratedTrees.Select(tree => tree.ToString()));
    }
}
